from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class File(SchemaObject):
    file_id = SchemaField(name='fileId')
    size_in_byte = SchemaField(name='sizeInByte')

    def __init__(self, file_id, size_in_byte):
        self.file_id = file_id
        self.size_in_byte = size_in_byte

        super(File, self).__init__()


class GetSnapshotOperationsInformationV1(SchemaObject):
    filter_regx = SchemaField(name='filterRegx')
    reason = SchemaField(name='reason')
    coverage = SchemaField(name='coverage')
    originator = SchemaField(name='originator')
    operation_id = SchemaField(name='operationId')
    status = SchemaField(name='status')
    remote_name = SchemaField(name='remoteName')
    failure_info = SchemaField(name='failureInfo')
    files = SchemaField(name='files', many=True, klass=File)

    def __init__(self, filter_regx, reason, coverage, originator, operation_id, status, remote_name,
                 failure_info, files):
        self.filter_regx = filter_regx
        self.reason = reason
        self.coverage = coverage
        self.originator = originator
        self.operation_id = operation_id
        self.status = status
        self.remote_name = remote_name
        self.failure_info = failure_info
        self.files = files

        super(GetSnapshotOperationsInformationV1, self).__init__()


